mapper.select:
select count(distinct nr.notice_id) from sys_notice_recipient nr inner join sys_notice n on n.notice_id = nr.notice_id where nr.user_id = #{userId} and nr.notice_id in
#{noticeId}
and n.lifecycle_status = 'PUBLISHED' and n.status = '0' and (n.expire_time is null or n.expire_time > sysdate())

select u.user_id as userId, u.nick_name as nickName, d.dept_name as deptName, r.read_time as readTime from sys_notice_read r inner join sys_notice_recipient nr on nr.notice_id = r.notice_id and nr.user_id = r.user_id inner join sys_user u on u.user_id = r.user_id and u.del_flag = '0' left join sys_dept d on d.dept_id = u.dept_id where r.notice_id = #{noticeId}
and (u.user_name like concat('%', #{searchValue}, '%') or u.nick_name like concat('%', #{searchValue}, '%'))
order by r.read_time desc
